head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elastic_search.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 내용이 없습니다.";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.vBzProcsNo = "", scwin.vIsurCd = "", scwin.vReload = "", scwin.vJobType = "";
scwin.vScrenID = "ULDSTF07106.xml";

//파일삭제시 ElasticSearch 색인 호출
scwin.isFileDelete = false;
scwin.eBzProcsNo, scwin.eComideDd, scwin.eSeq;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_set_code = function() {
    var strCodeYN = "N^N,Y^Y";
    cmb_CORP_LGSHRHD_YN.CBData = strCodeYN;
    cmb_NML_COM_LGSHRHD_YN.CBData = strCodeYN;
    cmb_OLDSTK_SALE_YN.CBData = strCodeYN;
    cmb_LAWST_YN.CBData = strCodeYN;
    cmb_CMIT_CONTN_YN.CBData = strCodeYN;
    cmb_PRTDEPO_EXTN_YN.CBData = strCodeYN;
    var arrCid = [{
        cid: "COMITE_INVSTG_RSLT_CD",
        cnm: "cmb_ComiteInvstgRsltCd"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='COMITE_INVSTG_RSLT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_search_reqinf = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prelminvstg.select.cmtdelib.reqinf.condition" + "&{P}param01=" + scwin.vBzProcsNo;
    //"&{P}param01=" +  dts_Cmt.NameString(dts_Cmt.RowPosition, "BZ_PROCS_NO");

    dts_ReqInf.DataID = encodeURI(url);
    dts_ReqInf.reset();
};
scwin.fn_search_cmt = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prelminvstg.select.kosdaq.cmtdelib.condition" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_Cmt.DataID = encodeURI(url);
    dts_Cmt.reset();
};
scwin.fn_search_issue = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingkosdaq.select.cmtdelib.total.issue.comite" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_Issue.DataID = encodeURI(url);
    dts_Issue.reset();
};
scwin.fn_search_ret = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIBRETR_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prelminvstg.select.cmtdelibretr.condition" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_Retr.DataID = encodeURI(url);
    dts_Retr.reset();
};
scwin.fn_save = function(jobType) {
    var vScrenProcTpCd;
    scwin.vJobType = jobType;
    if (jobType == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if (jobType == "D") {
        if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
            dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", js_emp_no);
            tr_Save.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelibcomite";
            tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf, I:pInpCmt=dts_Cmt, I:pFile=dts_fileList)";
            tr_Save.KeyName = "toinb_dataid4";
            tr_Save.Post();
        }
    }
    if (jobType == "I" || jobType == "U") {
        if (!$c.cp.isModified(dts_Retr) && !$c.cp.isModified(dts_ReqInf) && !$c.cp.isModified(dts_fileList)) {
            $c.win.alert(scwin.MGS_NO_UPDT);
            return;
        }
        var rtn = confirm('저장 하시겠습니까?');
        if (rtn == 1) {
            if ($c.cp.isModified(dts_Retr) || $c.cp.isModified(dts_ReqInf)) {
                dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", js_emp_no);
                tr_Save.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelibretr";
                tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf, I:pInpCmt=dts_Retr, I:pFile=dts_fileList)";
                tr_Save.KeyName = "toinb_dataid4";
                tr_Save.Post();
            } else if ($c.cp.isModified(dts_fileList)) {
                scwin.fn_file_save();
            }
        }
    }
};
scwin.fn_file_save = function() {
    tr_File.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveFiledelibretr&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    tr_File.KeyValue = "JSP(I:pFile=dts_fileList)";
    tr_File.Post();
};
scwin.fn_file_read = function() {
    tr_ReadFile.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFiledelibretr&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    tr_ReadFile.KeyValue = "JSP(O:pOutput=dts_fileList)";
    tr_ReadFile.Post();
};
scwin.fn_delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {
        scwin.vReload = "Y";
        if (dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "ATTACH_FILE_NM2") != "") {
            scwin.isFileDelete = true;
            scwin.eBzProcsNo = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
            scwin.eComideDd = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_DD");
            scwin.eSeq = "2";
        }
        $c.cp.removeRow(dts_Cmt, dts_Cmt.getRowPosition());
        scwin.fn_save("D");
    }
};
scwin.fn_modify = async function() {
    if (dts_Cmt.getRowPosition() > 0) {
        scwin.fn_GetPar = fn_GetParUpdate;
        scwin.fn_SetPar = undefined;
        await $c.frame.CreateDialogFrame("DLG_ISSUE_DTL", "/lstinvstg/ULDSTF07109.gfm", "위원회결과 수정", 10, 10, 580, 430, "window");
    }
};
scwin.fn_insert = async function() {
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    await $c.frame.CreateDialogFrame("DLG_ISSUE_DTL", "/lstinvstg/ULDSTF07109.gfm", "위원회결과 입력", 10, 10, 580, 430, "window");
};
scwin.fn_insertRetr = function() {
    dts_Retr.insertRow();
    dts_Retr.setCellData(dts_Retr.getRowPosition(), "BZ_PROCS_NO", scwin.vBzProcsNo);
};
scwin.fn_GetParNew = function(arrPar) {
    arrPar[0] = scwin.vBzProcsNo;
    return arrPar.length;
};
scwin.fn_GetParUpdate = function(arrPar) {
    arrPar[0] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    arrPar[1] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_DD");
    return arrPar.length;
};
scwin.fn_setKeyCtrOnAdd = function() {
    $c.lc.fn_setCtrWritable([med_ComiteDd]);
};
scwin.fn_setKeyCtrOnUpd = function() {
    $c.lc.fn_setCtrReadOnly([med_ComiteDd]);
};
scwin.fn_set_dataset_header = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_filedown = function() {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO") + "&attach_seq=1&gubun=37";
};
scwin.fn_list_sync = function() {
    scwin.fn_search_cmt();
};
scwin.fn_list_sync_refrsh = function() {
    scwin.vReload = "Y";
    scwin.fn_search_cmt();
};
scwin.fn_GetParDtl = function(arrPar) {
    arrPar[0] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD");
    arrPar[1] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD");
    arrPar[2] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM");
    arrPar[3] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParDtl = function(arrPar) {
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD", arrPar[0]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD", arrPar[1]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM", arrPar[2]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM", arrPar[3]);
    scwin.fn_setFornListCntrNm();
};
scwin.fn_setFornListCntrNm = function() {
    var FORN_COM_FST_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD");
    var FORN_COM_SCND_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD");
    var FORN_FST_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM");
    var FORN_SCND_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM");
    switch (FORN_COM_FST_LIST_CNTR_CD) {
        case '1':
            FORN_FST_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_FST_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_FST_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    switch (FORN_COM_SCND_LIST_CNTR_CD) {
        case '1':
            FORN_SCND_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_SCND_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_SCND_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    $c.stf.setObjectValue(txa_FORN_COM_INVSTG_CONT, "(" + FORN_FST_LIST_MISC_CNTR_NM + "," + FORN_SCND_LIST_MISC_CNTR_NM + ")");
};
scwin.fn_filedown = function() {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + scwin.vBzProcsNo + "&comite_dd=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_DD") + "&attach_seq=2&gubun=38";
};
scwin.fn_checkComiteDd = function(comiteDd) {
    if (dts_Cmt.getTotalRow() > 0) {
        for (var i = 0; i < dts_Cmt.getTotalRow(); i++) {
            if (comiteDd == dts_Cmt.getCellData(i, "COMITE_DD")) {
                return false;
            }
        }
    }
    return true;
};
scwin.callElasticFileNoti = function() {
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiElasticCommon",
            P_bzProcsNo: scwin.eBzProcsNo,
            P_comiteDd: scwin.eComideDd,
            P_seq: scwin.eSeq,
            url: "/index/tbld_comite_rslt_attach/kafka",
            type: "POST"
        },
        async: true
    });
    scwin.isFileDelete = false;
};
scwin.indexingElasitcSearch = function() {
    comite_rslt_attach(scwin.eBzProcsNo, scwin.eComideDd, "2"); //상장예비심사결과 상세조회
    list_invstg_attach(scwin.eBzProcsNo, "00", "10"); //예비심사
    list_invstg_attach(scwin.eBzProcsNo, "00", "04"); //공모 
    list_invstg_attach(scwin.eBzProcsNo, "00", "40"); //상장심사 

};
scwin.dts_Cmt_OnLoadCompleted = function(rowcount) {

};
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    if (dts_Cmt.getTotalRow() > 0) {
        scwin.fn_setFornListCntrNm();
    }
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {

};
scwin.dts_Retr_OnLoadCompleted = function(rowcount) {
    if (dts_Retr.getTotalRow() > 0) {

    } else {
        scwin.fn_insertRetr();
    }
    scwin.fn_file_read();
};
scwin.tr_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_Save_OnSuccess = function() {
    if (scwin.vJobType == "I") {
        $c.win.alert("성공적으로 저장 되었습니다.");
    } else if (scwin.vJobType == "U") {
        $c.win.alert("성공적으로 수정 되었습니다.");
    } else if (scwin.vJobType == "D") {
        scwin.indexingElasitcSearch();
        $c.win.alert("성공적으로 삭제 되었습니다.");
        if (scwin.isFileDelete) {
            //파일이 삭제되어 ElasticSearch 호출
            scwin.callElasticFileNoti();
        }
    }
    scwin.fn_search_ret();
};
scwin.img_Insert_onclick = function() {
    scwin.fn_insert();
};
scwin.img_Modify_onclick = function() {
    scwin.fn_modify();
};
scwin.img_Delete_onclick = function() {
    scwin.fn_delete();
};
scwin.img_Save_onclick = function() {
    scwin.fn_save("I");
};
scwin.btn_insert_file_onclick = function() {
    if (dts_fileList.getCellData(1, "filename") == "") {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_fileList.setCellData(1, "fileInfo", inf_find.getValue());
            txb_file_name.setValue(inf_find.getValue());
        } else {
            //dts_fileList.DeleteRow(1);

            //txb_file_name5.value = "";

        }
    }
};
scwin.btn_delete_file_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    txb_file_name.setValue("");
};
scwin.btn_save_file_onclick = function() {
    if (dts_fileList.getRowStatus(1) == 0 && dts_fileList.getCellData(1, "filename") != "") {
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + scwin.vBzProcsNo + "&attach_seq=1&gubun=37";
    }
};
scwin.btn_fileSave2_onclick = function() {
    if (dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "ATTACH_FILE_NM2") != "") {
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO") + "&comite_dd=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_DD") + "&attach_seq=2&gubun=38";
    }
};
scwin.tr_File_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_File_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    //fn_search();	
    scwin.fn_file_read();
    scwin.fn_search_ret();
};
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    txb_file_name.setValue("");
    if (rowcount > 0) {
        txb_file_name.setValue(dts_fileList.getCellData(1, "filename"));
    }
};
scwin.dts_fileList_OnLoadError = function() {

};
scwin.grd_List_OnDblClick = function(row, colid) {
    if ("ATTACH_FILE_NM2" == colid) {
        if (dts_Cmt.getCellData(row, "ATTACH_FILE_NM2") != "") {
            scwin.fn_filedown();
        }
    } else {
        scwin.fn_modify();
    }
};
scwin.img_Cmit_onclick = async function() {
    var wth = 1350;
    var hgt = 800;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    var frameId = "frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("CMIT", "/lstmgt/ULDSTF41620.gfm?" + frameId, "확약사항관리", pt.x, pt.y, wth, hgt, "window");
};
scwin.gform_onload = function() {
    var arr = new Array();
    $c.stf.showObj(panel_Term, false);
    $c.stf.showObj(inf_find, false);
    $c.stf.showObj(txb_seq, false);
    scwin.fn_set_code();
    scwin.fn_set_dataset_header();
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    scwin.vIsurCd = (arr.length >= 1 ? arr[0] : "");
    scwin.vBzProcsNo = (arr.length >= 2 ? arr[1] : "");
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : ""));
    med_BillSubmitDd.setValue((arr.length >= 3 ? arr[3] : ""));
    if (arr.length > 2) {
        scwin.fn_search_cmt();
    }
    scwin.fn_search_reqinf();
    scwin.fn_search_issue();
    scwin.fn_search_ret();
    var parentframeID = $c.stf.getQuery(frame.srcUrl, "frameID");
    if (parentframeID.indexOf('STF60000') != -1) {
        $c.stf.showObj(img_Insert, false);
        $c.stf.showObj(img_Modify, false);
        $c.stf.showObj(img_Delete, false);
        $c.stf.showObj(img_Save, false);
        $c.stf.showObj(img_issue, false);
    } else {
        $c.win.alert("주요 이슈사항을 반드시 입력하세요.");
    }
};
scwin.img_issue_onclick = async function() {
